  if [ "$SIM" = verilator ]; then
    verilator --binary -j 8 -Wno-fatal --top-module tb_dsdv_bk_sel_x_lp -GMUT=$m -DOT_S81PH_SEL_SAFE -DOT_S81PH_SEL_FRPR -DOT_S81PH_SEL_ILD -DOT_DSDV_BK_HARD $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
